import {createChatOrchestrator} from './chatOrchestrator.js';
import type {AIProvider, MessageChunk} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';

const promptBuilder = new PromptBuilder({identity: 'You are a test assistant.'});

const session: ChatSession = {
  sessionId: 'test-session',
  userId: 'user-1',
  entries: [{role: 'user', content: 'hello', timestamp: new Date().toISOString()}],
};

const rejectingWith = (reason: unknown): AIProvider => ({
  // eslint-disable-next-line require-yield
  async *sendMessage(): AsyncGenerator<MessageChunk> {
    throw reason;
  },
  async generateStructured<T>(): Promise<T> {
    return {} as T;
  },
});

const seenByOnError = async (reason: unknown) => {
  const seen: Error[] = [];
  const orchestrator = createChatOrchestrator(rejectingWith(reason), promptBuilder, undefined, {
    hooks: {
      onError: async (_session, error) => {
        seen.push(error);
      },
    },
  });
  const thrown = await orchestrator.processMessage(session).then(
    () => 'resolved' as unknown,
    (caught: unknown) => caught
  );
  return {seen, thrown};
};

describe('ChatOrchestrator onError cause preservation', () => {
  it('wraps a plain object rejection in an Error whose cause is that object', async () => {
    const reason = {code: 503};
    const {seen, thrown} = await seenByOnError(reason);

    expect({count: seen.length, cause: seen[0]?.cause, thrown}).toEqual({count: 1, cause: reason, thrown: reason});
    expect(seen[0]?.cause).toBe(reason);
  });

  it('wraps an undefined rejection in an Error whose cause is undefined and rethrows undefined', async () => {
    const {seen, thrown} = await seenByOnError(undefined);

    expect({count: seen.length, isError: seen[0] instanceof Error, hasCause: seen[0] && 'cause' in seen[0], thrown}).toEqual({
      count: 1,
      isError: true,
      hasCause: true,
      thrown: undefined,
    });
  });

  it('passes an Error rejection to onError as the same instance', async () => {
    const reason = new Error('fail');
    const {seen} = await seenByOnError(reason);

    expect(seen[0]).toBe(reason);
  });
});
EOF
